arguments.command:
python -c "
import parse
r = parse.parse('''
    letters: {:w}
    non-letters: {:W}
    whitespace: \"{s}\"
    non-whitespace: \t{:S}\n
    digits: {:d}
    non-digits: {:D}
    numbers with thousands: {:n}
    fixed-point: {:f}
    floating-point: {:e}
    general numbers: {:g} {:g}
    binary: {:b}
    octal: {:o}
    hex: {:x}
    ISO 8601 e.g. {:ti}
    RFC2822 e.g. {:te}
    Global e.g. {:tg}
    US e.g. {:ta}
    ctime() e.g. {:tc}
    HTTP e.g. {:th}
    time: {:tt}
    final value: {}
''', '''
    letters: abcdef_GHIJLK
    non-letters: !@#%\$ *^%
    whitespace: \"   \t\n\"
    non-whitespace: \tabc\n
    digits: 0xabcdef
    non-digits: .;';\'\",./
    numbers with thousands: 1234567890
    fixed-point: 3.14159
    floating-point: 3.14159E2
    general numbers: 3.14159 1.23e4
    binary: 0b101010
    octal: 0o777
    hex: 0xabc
    ISO 8601 e.g. 2009-10-21T16:00:00
    RFC2822 e.g. Tue Oct 21 16:00:00 2009
    Global e.g. Tuesday, October 21, 2009
    US e.g. 10/21/2009
    ctime() e.g. Wed Jun 24 21:35:56 2009
    HTTP e.g. Tue, 21 Oct 2009 16:00:00 GMT
    time: 16:00:00
    final value: done
''')
print('Result:', r)
" 2>&1 | grep -v "SyntaxWarning" | tail -10
